T["All Oasis users get a warning when a banned player is in their group, invites them or wants to trade - and see it in the tooltip."] = "BAN対象者がパーティにいる、招待してきた、取引しようとした場合、Oasisユーザー全員に警告が出ます。ツールチップにも表示されます。"
