T["Distribute all sign-ups into groups, invite and sort right away."] = "参加登録者を全員パーティに振り分け、すぐに招待して並べ替えます。"
T["Everyone from the chosen rank up (rank 1 = guild master) sees this hub and may change modules and announcements for the guild. Only the guild master sets the limit."] = "選択したランク以上 (ランク1 = ギルドマスター) の全員がこの管理画面を表示でき、ギルドのモジュールとアナウンスを変更できます。この基準はギルドマスターだけが設定できます。"
T["Everyone up to the chosen rank (rank 1 = Guild Master) sees this hub and may change modules, appearance and announcements for the guild. Only the Guild Master sets the limit."] = "選択したランク以上 (ランク1 = ギルドマスター) の全員がこの管理画面を表示でき、ギルドのモジュール、外観、アナウンスを変更できます。この基準はギルドマスターだけが設定できます。"
T["Everyone from the chosen rank up sees this hub and may change modules, announcements and events for the guild."] = "選択したランク以上の全員がこの管理画面を表示でき、ギルドのモジュール、アナウンス、イベントを変更できます。"
