T["10% faster while dead; free casts for 2 min after resurrection."] = "死亡中は移動速度10%上昇。復活後2分間は詠唱コストなし。"
T["Ran back to your own corpse as a ghost. It's about the journey."] = "ゴーストのまま自分の死体まで走って戻った。大事なのは道のり。"
