T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "ダンジョンマップには座標がありません。ここをクリックし、マップ上の現在地をクリックしてください。離れた2か所で行うと、Oasisがあなたとパーティをマップに表示します - ギルド全体に有効。"
