T["The guild isn't looking for anything from this dungeon."] = "ギルドは今このダンジョンのものを探していません。"
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "ギルドはまだ戦利品ポイントを付与していません - レイドリーダーがレイドを開始すると数値が表示されます。"
T["The guild bank hasn't been read yet"] = "ギルドバンクは未読み取りです"
T["The guild bank hasn't been read yet. As soon as someone with Oasis opens the guild vault, everything shows up here – for the whole guild."] = "ギルドバンクはまだ読み取られていません。Oasis利用者がギルド金庫を開くと、ここにすべて表示されます – ギルド全体に。"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーとアシスタントを指名します (名前またはギルドランク以上)。進行中のレイドではレイドリーダーとアシスタントも含まれます。"
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーを指名します。進行中のレイドではレイドリーダーとアシスタントも含まれます。"
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーを指名します。進行中のレイドではレイドリーダーも含まれます。"
T["The guild leadership only allows group searches from a higher rank."] = "ギルド運営はパーティ募集をより高いランクからのみ許可しています。"
T["The guild leadership only allows polls from a higher rank."] = "ギルド運営は投票をより高いランクからのみ許可しています。"
T["Guild leadership has muted sound effects for you."] = "ギルド運営があなたのサウンド効果をミュートしました。"
T["The guild leadership has disabled the partner search."] = "ギルド運営が仲間探しを無効にしました。"
T["The guild leadership has disabled open invites - challenge someone directly."] = "ギルド運営がオープン招待を無効にしました - 誰かに直接挑戦してください。"
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "どのランクに許可するかは、ギルド運営が 王冠 > モジュール で設定します。"
T["Guild Leadership is visible to ranks up to %d (%s). Your rank: %d."] = "ギルド運営を閲覧できるのはランク%d (%s) まで。あなたのランク: %d。"
T["WoW's guild finder helps - neutral, no ads."] = "WoWのギルド検索が役立ちます - 中立、広告なし。"
T["Only the guild master sets the limit. Rank 1 = guild master."] = "上限はギルドマスターのみが設定します。ランク1 = ギルドマスター。"
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "ボタンはコマンドをチャット欄に入力します - Enterを押すと実行されます。"
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "ショートカットはWoWのキー割り当ての AddOns > Oasis にもあります。EscでOasisウィンドウが閉じます (戦闘中は不可 - Escはゲーム側のものです)。"
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "ショートカットはWoWのキー割り当ての AddOns > Oasis にもあります。最後にOasisウィンドウ内をクリックしていれば、Escで閉じます。"
T["The bar is there from login and stays - the X on the window only closes the window."] = "バーはログイン時から常に表示されます - ウィンドウのXはウィンドウだけを閉じます。"
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "バーは上に巻き上がって隠れます。マウスを上端に寄せると降りてきます (上部にドッキング時のみ)"
