T["Oasis had touched Blizzard buttons (action bars, bags, tooltip, chat) (fixed in 0.5.504 - please update Oasis)."] = "Oasis が Blizzard のボタン (アクションバー、バッグ、ツールチップ、チャット) に触れていました (0.5.504 で修正済み - Oasis を更新してください)。"
