T["Oasis can do a lot. Pick what you want to use - the rest stays off for now and can be turned on anytime under 'Discover'."] = "Oasis は多機能です。使いたいものを選んでください - 残りはひとまずオフのままで、「発見」からいつでもオンにできます。"
