T["Oasis reads Blizzard's built-in damage meter after every fight - in instances too."] = "Oasis は戦闘のたびに Blizzard 内蔵のダメージメーターを読み取ります - インスタンス内でも同様です。"
T["After every fight Oasis reads Blizzard's built-in damage meter - the combat log is locked for addons in WoW Forever. Others need Oasis 0.5.577 or newer. Values Blizzard keeps secret (e.g. in instances) don't count."] = "Oasis は戦闘のたびに Blizzard 内蔵のダメージメーターを読み取ります - WoW Forever ではアドオンから戦闘ログを利用できません。他のプレイヤーは Oasis 0.5.577 以降が必要です。Blizzard が秘匿する値 (インスタンス内など) は集計されません。"
