T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "よく参加していて獲得が少ない人が「ニード」で優先されます。ポイントの一部は毎週失効します。"
T["Anyone who signs up with a fitting role is invited to your group right away."] = "合うロールで応募した人は、すぐにあなたのパーティへ招待されます。"
