T["Tools"] = "ツール"
T["Stats"] = "ステータス"
T["stats do nothing for your role"] = "ステータスがロールに合いません"
T["stats for info only"] = "ステータスは参考のみ"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "キャラクターのステータス、年鑑、デイリー目標、記録、冒険。"
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "ステータス: +ヒーリング、知性、精神、MP5;武器: 杖、または片手武器 + ヒーリング付きオフハンド;回復: RejuvenationとRegrowthを先がけ、大きな被弾にはHealing Touch;ヒント: マナにはInnervate、倒れたヒーラーにはRebirth"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "ステータス: +ヒーリング、知性、スペルクリティカル (Illuminationでマナ還元)、MP5;武器: 片手武器 + ヒーリング付きオフハンド/盾;回復: 小さなダメージにはFlash of Light、大きな被弾にはHoly Light (低ランク);ヒント: Blessingを配り、ヘイトを取ったらDivine Protection"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "ステータス: +ヒーリング、MP5、知性 - 精神は効果が薄い;武器: 片手武器 + ヒーリング付き盾;回復: パーティにはChain Heal、タンクにはHealing Wave (低ランク);ヒント: Mana Spring Totemを設置、タンクにEarth Shield"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "ステータス: +ヒーリング、精神 (Meditation: 詠唱中もマナ回復)、知性、MP5;武器: 杖、または片手武器 + ヒーリング付きオフハンド、ワンド;回復: RenewとPower Word: Shieldを先がけ、タンクにはGreater Heal (低ランク);ヒント: パーティにはPrayer of Healing、ヘイトを取ったらFade"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "ステータス: アーマー (Bear Formで倍増)、スタミナ、敏捷 (回避 + アーマー);武器: ダメージは無関係 - ステータスのみ重要 (スタミナ付きの杖/ポールアーム);ローテーション: Maul、集団にはSwipe、Demoralizing Roar;ヒント: 筋力で脅威値アップ、開幕にEnrage"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "ステータス: 筋力 (1ポイント = 2 AP)、敏捷 (AP + クリティカル)、クリティカル、ヒット+9 %まで;武器: ダメージは無関係 - ステータスのみ重要;ローテーション: Claw/Shredでコンボポイント、その後Ferocious Bite;ヒント: パワーシフト (フォームをかけ直す) でエナジー回復、ステルスから開幕"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "ステータス: 筋力 (1ポイント = 2 AP)、クリティカル (Flurry発動 = 攻撃速度アップ)、ヒット+9 %まで;武器: 遅い両手武器 - Windfuryは1振りごとに発動するので、遅いほど高ダメージ;ローテーション: Windfury Weapon、Stormstrike、Earth Shock;ヒント: パーティにStrength of Earth TotemとWindfury Totem"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "ステータス: 筋力 (1ポイント = 2 AP)、クリティカル、ヒット+9 %まで;武器: 遅い両手武器 - SealとJudgementは1振りごとに効果;ローテーション: Seal of Righteousness/Command、Judgement、Sealをかけ直す;ヒント: Consecrationはマナに余裕があるときだけ、自分にBlessing of Might"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "ステータス: ヒット+9 %まで、敏捷 (1 AP、約29 = 1 %クリティカル)、AP、クリティカル;武器: Combat = 速いオフハンド、遅いメインハンド (Sinister Strike); Backstabにはダガー;ローテーション: コンボポイントを貯め、Slice and Diceを維持、その後Eviscerate;ヒント: 二刀流は通常攻撃が外れやすい - ヒットが最重要"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "ステータス: ヒット+9 %まで、敏捷 (遠隔AP 2、約53 = 1 %クリティカル)、AP、知性;武器: 遅い遠隔武器 (1発のダメージが大きい)、ステータス付き近接武器;ローテーション: Hunter's Mark、Auto Shot、合間にAimed Shot/Multi-Shot;ヒント: ペットにエサを与えて機嫌を保つ、CCにFreezing Trap (四角)"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "ステータス: ヒット+9 %まで、筋力 (1ポイント = 2 AP)、クリティカル (敏捷約20 = 1 %);武器: 遅い両手武器 (Mortal Strike、Heroic Strikeは1振りごとに効果);ローテーション: レイジを貯め、Mortal Strike / Bloodthirst、Whirlwind、余ったレイジはHeroic Strike;ヒント: 戦闘前にBattle Shout、HP 20 %未満でExecute"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "ステータス: 防御 (440 = レベル60でボスにクリティカルされない)、スタミナ、アーマー、ブロック;武器: 片手武器 + 盾、速い武器 = レイジ増;ローテーション: Shield Slam/Revenge、ターゲットにSunder Armor、レイジが多いときHeroic Strike;ヒント: ヒットがあるとTauntやアビリティが外れにくい"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "ステータス: 防御、スタミナ、アーマー、次に脅威値のためのスペルダメージ;武器: 片手武器 (できればスペルダメージ付き) + 盾;ローテーション: Righteous Furyをオン、集団にはConsecration、Holy Shieldを維持;ヒント: マナが厳しい - Seal of Wisdomか知性を用意"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "ステータス: スペルダメージ、スペルクリティカル (Elemental Focusでマナ節約)、知性、MP5;武器: 片手武器 + スペルダメージ付き盾/オフハンド;ローテーション: Lightning Boltを連発、集団にはChain Lightning、Flame Shock;ヒント: レイドではスペルヒット+16 %まで、マナ切れ対策にMana Spring Totem"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "ステータス: スペルダメージ、スペルクリティカル、知性、レイドではスペルヒット+16 %まで;武器: 杖、または片手武器 + スペルダメージ付きオフハンド;ローテーション: Moonfire + Insect Swarm、その後WrathかStarfire;ヒント: マナが減ったら自分にInnervate"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "ステータス: スペルダメージ、スペルヒット+16 %まで (レイド)、スタミナ、知性;武器: 杖、またはダガー + スペルダメージ付きオフハンド、残りマナ用にワンド;ローテーション: Corruption + カース、その後Shadow Bolt; 飲み物の代わりにLife Tap;ヒント: スタミナは二重に得 (Life Tap、Voidwalker/Soul Link)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "ステータス: スペルダメージ、スペルヒット+16 %まで (レイド)、マナ用に精神;武器: 杖、または片手武器 + スペルダメージ付きオフハンド;ローテーション: Shadow Word: Pain、Mind Blast、Mind Flay;ヒント: Shadowformを常時維持、Vampiric Embraceでパーティを回復"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "ステータス: スペルダメージ、次にスペルヒット+16 %まで (レイドボス)、知性、スペルクリティカル;武器: スペルダメージ付きの杖、残りマナ用にワンド;ローテーション: FrostboltまたはFireballを連発、マナ切れ時にEvocation;レベリング: 知性と精神 = 休憩が減る、パーティではシープ (月) を担当"
