T["In a group WoW does not tell addons who landed a hit. Oasis only counts a critical hit if it directly follows your own attack and matches the damage meter after the fight. Marked as estimated in the ranking."] = "パーティ中、WoWは誰の攻撃が当たったかをアドオンに伝えません。Oasisは、自分の攻撃の直後に発生し、戦闘後にダメージメーターと一致するクリティカルヒットだけを数えます。ランキングでは推定値として表示されます。"
T["WoW locks some functions for addons (combat, bosses, chat input). This shows which function it was and what Oasis did before."] = "WoWは一部の機能をアドオンに対して制限しています (戦闘、ボス、チャット入力)。ここには、どの機能だったか、その前にOasisが何をしたかが表示されます。"
