T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "「良い / 悪い / 装備不可」を効果 (DPS、HP、アーマー) とステータス表付きで表示します。Blizzardの比較はShiftを押したときだけ表示されます。独自の比較機能を持つnesUIが読み込まれている場合、Oasisは何も表示しません (重複防止) - nesUI側で/nes vergleichを使ってオフにできます。"
T["Shows better / worse / can't equip with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI with its own comparison is loaded, Oasis shows nothing (otherwise doubled) - turn it off there with /nes vergleich."] = "「良い / 悪い / 装備不可」を効果 (DPS、HP、アーマー) とステータス表付きで表示します。Blizzardの比較はShiftを押したときだけ表示されます。独自の比較機能を持つnesUIが読み込まれている場合、Oasisは何も表示しません (重複防止) - nesUI側で/nes vergleichを使ってオフにできます。"
