T["Now and then shows classic Barrens chat lines in General - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent."] = "一般チャットにBarrensチャットの定番ネタをときどき表示します - Chuck Norris、Mankrik's wife ... あなたにだけ表示され、何も送信されません。"
T["Now and then shows classic Barrens chat lines in General - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent. Click: switch"] = "一般チャットにBarrensチャットの定番ネタをときどき表示します - Chuck Norris、Mankrik's wife ... あなたにだけ表示され、何も送信されません。クリック: 切り替え"
T["Shows which materials green, blue and epic items can disenchant into"] = "緑・青・エピックのアイテムをディスエンチャントして得られる素材を表示"
