T["Shows you the crown and Guild Leadership like a Guild Master – only on your PC. The guild sees none of it."] = "ギルドマスターと同じように王冠とギルド運営を表示します – あなたのPCだけです。ギルドには何も見えません。"
T["Shows a notice as soon as a guildmate creates a new event"] = "ギルドメンバーが新しいイベントを作成すると通知を表示"
