T["Shows in the listing that you talk by voice (Discord etc.). Joining is still handled by Blizzard / your group leader."] = "ボイスチャット (Discordなど) で話していることを募集に表示します。参加の処理は引き続きBlizzard / パーティリーダーが行います。"
T["Shows mains only. Alts are characters assigned to another main."] = "メインキャラのみ表示します。サブキャラは別のメインキャラに割り当てられたキャラクターです。"
