T["Shows at a glance who in the guild has the same quests and is online right now - one click invites them."] = "同じクエストを持ち、今オンラインのギルドメンバーをすぐ表示 - ワンクリックで招待できます。"
T["Shows unexplored areas dimmed (off by default)"] = "未探索エリアを暗く表示 (標準はオフ)"
T["Shows e.g. new messages or orders as a number next to the name"] = "新着メッセージや依頼などを名前の横に数字で表示"
